import math

class SegmentTree:
    def __init__(self, n):
        self.n = n
        self.tree = [float('inf')] * (4 * n)

    def update(self, idx, val):
        self._update(1, 0, self.n - 1, idx, val)

    def _update(self, node, start, end, idx, val):
        if start == end:
            self.tree[node] = min(self.tree[node], val)
            return
        mid = (start + end) // 2
        if idx <= mid:
            self._update(2 * node, start, mid, idx, val)
        else:
            self._update(2 * node + 1, mid + 1, end, idx, val)
        self.tree[node] = min(self.tree[2 * node], self.tree[2 * node + 1])

    def query(self, l, r):
        return self._query(1, 0, self.n - 1, l, r)

    def _query(self, node, start, end, l, r):
        if r < start or end < l:
            return float('inf')
        if l <= start and end <= r:
            return self.tree[node]
        mid = (start + end) // 2
        p1 = self._query(2 * node, start, mid, l, r)
        p2 = self._query(2 * node + 1, mid + 1, end, l, r)
        return min(p1, p2)

def min_coupons(N, trips):
    MAX_ZONES = 10
    seg_tree = SegmentTree(MAX_ZONES + 1)
    seg_tree.update(0, 0)
    last_time = 0
    total_cost = 0

    for z, t in trips:
        if t > last_time + 10000:
            seg_tree.update(z, float('inf'))
        cost = seg_tree.query(0, z) + 2 + abs(0 - z)
        seg_tree.update(z, cost)
        total_cost += cost
        last_time = t

    return total_cost

